const $=id=>document.getElementById(id);
const fieldLabels={advertiser:'Visible advertiser',visibleText:'Visible copy',language:'Language',cta:'Visible call to action',offer:'Visible offer',format:'Format category',hook:'Hook category',apparentAudience:'Apparent product use case',explanation:'Creative interpretation',uncertainty:'Limitations and uncertainty'};
const state={creatives:[],jobs:[],backend:localStorage.getItem('adlens-backend')||'',token:'',online:false,health:null,review:null,detail:null,db:null,view:'capture'};
function el(tag,attrs={},text){const e=document.createElement(tag);for(const [k,v]of Object.entries(attrs)){if(k==='class')e.className=v;else e.setAttribute(k,v);}if(text!==undefined)e.textContent=text;return e;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),6000);}
const db=await new Promise((resolve,reject)=>{const r=indexedDB.open('adlens',1);r.onupgradeneeded=()=>{r.result.createObjectStore('creatives',{keyPath:'id'});r.result.createObjectStore('visits',{keyPath:'id'});};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);}).catch(()=>null);state.db=db;
async function transaction(store,mode,fn){if(!db)throw new Error('Browser storage is unavailable. Enable site storage to save evidence.');return new Promise((resolve,reject)=>{const tx=db.transaction(store,mode);const request=fn(tx.objectStore(store));tx.oncomplete=()=>resolve(request?.result);tx.onerror=()=>reject(tx.error);});}
async function load(){state.creatives=await transaction('creatives','readonly',s=>s.getAll())||[];state.jobs=await transaction('visits','readonly',s=>s.getAll())||[];state.creatives.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));state.jobs.sort((a,b)=>b.createdAt.localeCompare(a.createdAt));render();}
async function saveCreative(c){await transaction('creatives','readwrite',s=>s.put(c));await load();}
async function api(route,options={}){const base=state.backend.replace(/\/$/,'');const res=await fetch(base+route,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:`Bearer ${state.token}`} : {}),...options.headers},signal:options.signal||AbortSignal.timeout(70000)});const body=await res.json().catch(()=>({error:'Backend returned an unexpected response.'}));if(!res.ok)throw new Error(body.error||`Request failed (${res.status}).`);return body;}
async function connection(){try{state.health=await api('/api/health',{signal:AbortSignal.timeout(5000)});state.online=!!state.health.ok;}catch{state.online=false;state.health=null;}
  $('connection-label').textContent=state.online?'Backend connected':'Screenshot workspace';document.querySelector('.dot').classList.toggle('online',state.online);
  $('mode-help').textContent=state.online?'Browser capture is ready. Review crops before sending them for AI analysis.':'URL capture needs a connected backend. You can upload screenshots and organise research here now.';
  $('backend-status').textContent=state.online?`Connected. AI ${state.health.analysisAvailable?'enabled · '+state.health.model:'not configured'}. Daily request limit: ${state.health.dailyLimit}.`:'Not connected. Upload screenshots, or run the self-hosted app to enable URL capture.';
}
function navigate(view){state.view=view;document.querySelectorAll('.view').forEach(e=>e.hidden=e.id!==view+'-view');document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('breadcrumb').replaceChildren(document.createTextNode('Workspace '),el('span',{},'/'),document.createTextNode({capture:' New capture',collection:' Creative collection',settings:' Settings'}[view]));if(view==='settings')$('backend').value=state.backend;window.scrollTo(0,0);}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));$('connection-button').onclick=()=>navigate('settings');document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('capture');};$('about').onclick=()=>$('about-dialog').showModal();document.querySelectorAll('.close').forEach(b=>b.onclick=()=>b.closest('dialog').close());
function domain(url){try{return new URL(url).hostname;}catch{return 'Uploaded screenshot';}}
function date(value){return new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});}
function render(){renderJobs();renderCollection();$('nav-count').textContent=state.creatives.length;}
function renderJobs(){const root=$('jobs');root.replaceChildren();$('visit-count').textContent=`${state.jobs.length} visits`;
  if(!state.jobs.length){const empty=el('div',{class:'empty'});empty.append(el('strong',{},'Your first research visit starts here'),el('p',{},'Capture a website or upload a screenshot to begin.'));root.append(empty);return;}
  for(const job of state.jobs.slice(0,8)){const row=el('div',{class:'job'}),info=el('div',{class:'job-info'});info.append(el('strong',{},job.url||job.name||'Uploaded screenshot'),el('p',{},`${date(job.createdAt)} · ${job.error||job.stage||'Ready for review'}`));row.append(el('span',{class:'job-icon','aria-hidden':'true'},'▤'),info,el('span',{class:'badge'+(job.status==='failed'?' error':'')},job.status==='capturing'?'Capturing':job.status==='failed'?'Stopped':job.status==='cancelled'?'Cancelled':'Review'));
    if(job.result?.screenshot){const b=el('button',{class:'button secondary'},'Review');b.onclick=()=>openReview(job);row.append(b);}
    if(job.status==='capturing'){const b=el('button',{class:'text-button'},'Cancel');b.onclick=async()=>{try{await api('/api/jobs/'+job.id,{method:'POST'});}catch(e){toast(e.message);}};row.append(b);}
    const remove=el('button',{class:'icon-button','aria-label':'Delete capture'},'×');remove.onclick=async()=>{if(!confirm('Delete this visit record? Saved creative crops will remain.'))return;try{if(job.source==='backend')await api('/api/jobs/'+job.id,{method:'DELETE'});await transaction('visits','readwrite',s=>s.delete(job.id));await load();}catch(e){toast(e.message);}};row.append(remove);root.append(row);}
}
function filtered(){const query=$('search').value.toLowerCase();return state.creatives.filter(c=>(!query||JSON.stringify({url:c.url,...c.fields}).toLowerCase().includes(query))&&(!$('hook-filter').value||c.fields?.hook===$('hook-filter').value)&&(!$('status-filter').value||c.status===$('status-filter').value));}
function renderCollection(){const stats=$('stats');stats.replaceChildren();for(const [value,label]of [[state.creatives.length,'captured creatives'],[state.creatives.filter(c=>c.status==='analysed').length,'AI analysed'],[new Set(state.creatives.map(c=>domain(c.url))).size,'observed sources']]){const s=el('div',{class:'stat'});s.append(el('strong',{},value),el('span',{},label));stats.append(s);}
  const selected=$('hook-filter').value;const hooks=[...new Set(state.creatives.map(c=>c.fields?.hook).filter(Boolean))].sort();$('hook-filter').replaceChildren(el('option',{value:''},'All hooks'),...hooks.map(h=>el('option',{value:h},h)));$('hook-filter').value=selected;
  const items=filtered();const counts={};for(const c of items)if(c.fields?.hook)counts[c.fields.hook]=(counts[c.fields.hook]||0)+1;
  $('patterns').textContent=Object.keys(counts).length?`Within this selection of ${items.length} creatives: `+Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([h,n])=>`${h} (${n})`).join(' · ')+'. Sample counts, not performance rankings.':'';
  const root=$('collection');root.replaceChildren();if(!items.length){const empty=el('div',{class:'empty'});empty.append(el('strong',{},state.creatives.length?'No matching creatives':'A collection built from your evidence'),el('p',{},state.creatives.length?'Try another search or filter.':'Confirm ad crops from a capture or uploaded screenshot.'));root.append(empty);return;}
  for(const c of items){const card=el('button',{class:'creative-card','aria-label':'Open '+(c.fields?.advertiser||'ad creative')});const visual=el('div',{class:'visual'});visual.append(el('img',{src:c.image,alt:c.fields?.advertiser||'Captured ad creative',loading:'lazy'}));const meta=el('div',{class:'creative-meta'});meta.append(el('strong',{},c.fields?.advertiser||'Unlabelled creative'),el('p',{},domain(c.url)+' · '+date(c.createdAt)));const tags=el('div',{class:'tags'});for(const text of [c.fields?.hook,c.status==='analysed'?'AI analysed':c.status==='manual'?'Manual notes':'Awaiting analysis'].filter(Boolean))tags.append(el('span',{class:'tag'},text));meta.append(tags);card.append(visual,meta);card.onclick=()=>openDetail(c.id);root.append(card);}
}
for(const id of ['search','hook-filter','status-filter'])$(id).addEventListener('input',renderCollection);
$('settings-form').onsubmit=async e=>{e.preventDefault();try{const value=$('backend').value.trim();if(value){const u=new URL(value);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)throw new Error('Use an HTTP or HTTPS backend URL without credentials.');if(location.protocol==='https:'&&u.protocol!=='https:')throw new Error('This hosted interface needs an HTTPS backend. For localhost, open the self-hosted app directly.');state.backend=u.origin;}else state.backend='';state.token=$('token').value;localStorage.setItem('adlens-backend',state.backend);await connection();toast(state.online?'Backend connected.':'Connection failed. Check the URL, token and ALLOWED_ORIGIN configuration.');}catch(e){toast(e.message);}};
let polling=false;
async function pollJob(id){if(polling)return;polling=true;try{let job;do{job=await api('/api/jobs/'+id);job.source='backend';await transaction('visits','readwrite',s=>s.put(job));await load();if(job.status==='capturing')await new Promise(r=>setTimeout(r,1500));}while(job.status==='capturing');if(job.result?.screenshot)openReview(job);else toast(job.error||'Capture stopped.');}catch(e){toast(e.message);}finally{polling=false;}}
$('capture-form').onsubmit=async e=>{e.preventDefault();if(!state.online){toast('Connect a capture backend in Settings, or upload a screenshot.');navigate('settings');return;}$('capture-submit').disabled=true;try{const job=await api('/api/jobs',{method:'POST',body:JSON.stringify({url:$('url').value})});await pollJob(job.id);}catch(e){toast(e.message);}finally{$('capture-submit').disabled=false;}};
async function decodeImage(src){const img=new Image();img.src=src;await img.decode();return img;}
async function readUpload(file){if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Choose a PNG, JPEG or WebP image under 8 MB.');const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const img=await decodeImage(src);if(img.width*img.height>40_000_000)throw new Error('Image is too large. Resize it before uploading.');return src;}
$('file').onchange=async()=>{const file=$('file').files[0];if(!file)return;try{const image=await readUpload(file);const job={id:crypto.randomUUID(),source:'upload',name:file.name,status:'review',stage:'User-supplied evidence',createdAt:new Date().toISOString(),result:{screenshot:image,candidates:[],context:{source:'User upload',region:'Unverified'},limitations:'Source URL, capture time and browser context are unverified.'}};await transaction('visits','readwrite',s=>s.put(job));await load();openReview(job);}catch(e){toast(e.message);}$('file').value='';};
async function openReview(job){state.review=job;$('review-title').textContent=job.source==='upload'?'Select the ad in your screenshot':'Review captured placements';$('review-context').textContent=(job.url||job.name)+' · '+job.result.limitations;$('review-image').src=job.result.screenshot;const image=await decodeImage(job.result.screenshot);$('crop-x').value=0;$('crop-y').value=0;$('crop-w').value=image.width;$('crop-h').value=image.height;$('crop-preview').hidden=true;const root=$('candidates');root.replaceChildren();if(!job.result.candidates.length)root.append(el('p',{class:'helper'},'No candidates. Select a region using the coordinate fields.'));
  for(const candidate of job.result.candidates){const row=el('div',{class:'candidate'});row.append(el('img',{src:candidate.image,alt:'Detected placement candidate'}),el('p',{},candidate.detection));const b=el('button',{class:'button secondary'},'Confirm ad');b.onclick=async()=>{try{await addCrop(candidate.image,job,candidate);b.disabled=true;b.textContent='Added to collection';}catch(e){toast(e.message);}};const exclude=el('button',{class:'text-button'},'Exclude');exclude.onclick=()=>{row.hidden=true;toast('Candidate excluded for this review. Reopen review to undo.');};const actions=el('div',{class:'button-row'});actions.append(b,exclude);row.append(actions);root.append(row);}
  if(!$('review-dialog').open)$('review-dialog').showModal();}
async function crop(){if(!state.review)throw new Error('Open a capture first.');const img=await decodeImage(state.review.result.screenshot);const [x,y,w,h]=['crop-x','crop-y','crop-w','crop-h'].map(id=>Number($(id).value));if(![x,y,w,h].every(Number.isInteger)||x<0||y<0||w<1||h<1||x+w>img.width||y+h>img.height)throw new Error(`Crop must fit within ${img.width} × ${img.height} pixels.`);const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(img,x,y,w,h,0,0,w,h);return {image:canvas.toDataURL('image/png'),rect:{x,y,width:w,height:h}};}
let drag=null;
function point(event){const r=$('review-image').getBoundingClientRect();return {x:Math.max(0,Math.min(r.width,event.clientX-r.left)),y:Math.max(0,Math.min(r.height,event.clientY-r.top)),r};}
$('crop-frame').onpointerdown=event=>{if(event.button!==0)return;const p=point(event);drag={start:p,end:p};$('crop-frame').setPointerCapture(event.pointerId);};
$('crop-frame').onpointermove=event=>{if(!drag)return;drag.end=point(event);const {start,end}=drag;const r=$('crop-frame').getBoundingClientRect();const box=$('crop-selection');box.hidden=false;Object.assign(box.style,{left:(start.r.left-r.left+Math.min(start.x,end.x))+'px',top:(start.r.top-r.top+Math.min(start.y,end.y))+'px',width:Math.abs(end.x-start.x)+'px',height:Math.abs(end.y-start.y)+'px'});};
$('crop-frame').onpointerup=async event=>{if(!drag)return;drag.end=point(event);const {start,end}=drag;drag=null;const img=await decodeImage(state.review.result.screenshot);const sx=img.width/start.r.width,sy=img.height/start.r.height;const x=Math.floor(Math.min(start.x,end.x)*sx),y=Math.floor(Math.min(start.y,end.y)*sy);const w=Math.min(img.width-x,Math.max(1,Math.floor(Math.abs(end.x-start.x)*sx))),h=Math.min(img.height-y,Math.max(1,Math.floor(Math.abs(end.y-start.y)*sy)));$('crop-x').value=x;$('crop-y').value=y;$('crop-w').value=w;$('crop-h').value=h;$('preview-crop').click();};
$('crop-frame').onpointercancel=()=>{drag=null;$('crop-selection').hidden=true;};
$('preview-crop').onclick=async()=>{try{const c=await crop();$('crop-preview').src=c.image;$('crop-preview').hidden=false;}catch(e){toast(e.message);}};
$('save-crop').onclick=async()=>{try{const c=await crop();await addCrop(c.image,state.review,{rect:c.rect,detection:'Manual crop'});}catch(e){toast(e.message);}};
async function addCrop(image,job,candidate){const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(image)))).map(x=>x.toString(16).padStart(2,'0')).join('');if(state.creatives.some(c=>c.hash===hash&&c.jobId===job.id)){toast('This crop is already in the collection.');return;}const creative={id:crypto.randomUUID(),hash,image,jobId:job.id,url:job.result.finalUrl||job.url||'',createdAt:candidate.capturedAt||job.createdAt,context:job.result.context,rect:candidate.rect,detection:candidate.detection,status:'review',fields:{},corrections:{}};await saveCreative(creative);toast('Ad crop added to collection.');}
function openDetail(id){state.detail=id;const c=state.creatives.find(c=>c.id===id);if(!c)return;$('detail-title').textContent=c.fields?.advertiser||'Ad evidence';$('detail-image').src=c.image;$('detail-source').textContent=(c.url||'User-supplied screenshot')+' · '+date(c.createdAt)+' · Region: '+(c.context?.region||'Unknown');$('detail-provenance').textContent=c.status==='analysed'?`AI interpretation · ${c.analysis.model}`:c.status==='manual'?'Manual notes · user supplied':'Not analysed';const root=$('detail-fields');root.replaceChildren();for(const [name,label]of Object.entries(fieldLabels)){if(name==='advertiser')root.append(el('div',{class:'field-group'},'OBSERVATIONS AND CATEGORIES'));if(name==='apparentAudience')root.append(el('div',{class:'field-group'},'INTERPRETATIONS · NOT VERIFIED TARGETING'));const field=el('div',{class:'field'});const input=el('textarea',{id:'field-'+name,rows:name==='visibleText'?3:2,placeholder:'Unknown / not yet analysed'});input.value=c.fields?.[name]||'';field.append(el('label',{for:'field-'+name},label),input);root.append(field);}$('analysis-message').textContent=state.online&&state.health?.analysisAvailable?'This sends the crop to OpenAI using your backend. Charges apply; no cost estimate is available.':'AI needs a backend with OPENAI_API_KEY configured. You can add manual notes.';$('analyse').disabled=!state.online||!state.health?.analysisAvailable;if(!$('detail-dialog').open)$('detail-dialog').showModal();}
$('save-notes').onclick=async()=>{const c=state.creatives.find(c=>c.id===state.detail);const fields=Object.fromEntries(Object.keys(fieldLabels).map(f=>[f,$('field-'+f).value.trim()]));c.fields=fields;c.correctedAt=new Date().toISOString();c.status=c.analysis?'analysed':'manual';await saveCreative(c);toast('Research notes saved.');openDetail(c.id);};
$('analyse').onclick=async()=>{const c=state.creatives.find(c=>c.id===state.detail);if(!c)return;if(c.correctedAt&&!confirm('Replace current fields with a fresh AI result? Your prior fields will be kept in history.'))return;$('analyse').disabled=true;$('analysis-message').textContent='Analysing the original crop…';try{const result=await api('/api/analyse',{method:'POST',body:JSON.stringify({image:c.image})});c.history=[...(c.history||[]),{fields:c.fields,at:new Date().toISOString()}];c.analysis=result;c.fields=result.fields;c.status='analysed';await saveCreative(c);openDetail(c.id);$('analysis-message').textContent=`Analysis completed in ${(result.latencyMs/1000).toFixed(1)}s${result.cached?' · reused cached result':''}. Review interpretations before using them.`;}catch(e){$('analysis-message').textContent=e.message;$('analyse').disabled=false;}};
function download(blob,name){const a=el('a',{href:URL.createObjectURL(blob),download:name});a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
$('download-image').onclick=async()=>{const c=state.creatives.find(c=>c.id===state.detail);download(await (await fetch(c.image)).blob(),'adlens-'+c.id+'.png');};
$('delete-creative').onclick=async()=>{if(!confirm('Delete this creative and its local notes?'))return;await transaction('creatives','readwrite',s=>s.delete(state.detail));$('detail-dialog').close();await load();toast('Creative deleted.');};
function csvCell(value){let s=String(value??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
$('export').onclick=()=>{const items=filtered();if(!items.length){toast('No creatives to export.');return;}const columns=['id','url','createdAt','status',...Object.keys(fieldLabels)];const rows=[columns,...items.map(c=>columns.map(k=>c[k]??c.fields?.[k]??''))];download(new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'adlens-research.csv');toast('Exported selected research metadata.');};
if(db)await load();else toast('Browser storage is unavailable; saving evidence will not work.');await connection();
if(state.online){try{const remote=await api('/api/jobs');for(const job of remote){job.source='backend';await transaction('visits','readwrite',s=>s.put(job));}await load();const active=remote.find(j=>j.status==='capturing');if(active)pollJob(active.id);}catch(e){toast(e.message);}}
